stylesheet:
@layer reset, base, tokens, recipes, utilities;
@layer tokens {
  :root, [data-theme=light] {
    --colors-blue-500: #3b82f6;
    --colors-red-500: #ef4444;
    --spacing-1: 0.25rem;
    --spacing-2: 0.5rem;
    --spacing-4: 1rem;
  }
  [data-theme=dark] {
    --colors-blue-500: #60a5fa;
    --colors-red-500: #f87171;
  }
}
@layer utilities {
  .lib-test-system__c_blue-500 { color: var(--colors-blue-500); }
  .lib-test-system__p_1 { padding: var(--spacing-1); }
  .lib-test-system__lg_p_4 { padding: var(--spacing-4); }
}

